	set stat = $$$OK
 set retVal = ""
 set resVal = ##class(Ens.Util.LookupTable).%ExistsTable(tableNm)
 if ( resVal = 0)
 {
	 $$$LOGERROR("LookupTable exception: " _ tableNm _ " does not exists")
	 set tExp = ##class(%Exception.General).%New()
	 set tExp.Name = "Setup error: " _ tableNm _ " does not exists"
	 set tExp.Code=999
	 set tExp.Location = "ItfLookup"
	 set tExp.Data = "Import data file " _ tableNm
	 Throw tExp
 }
 set retVal = ##class(Ens.Util.FunctionSet).Lookup(tableNm, key)
 if (retVal = "")
 {
   set retVal = "Unknown"
   set stat = $$$ERROR($$$GeneralError, "Value not found")
 }
 Quit stat

