 set maxErr = 5

&sql(Select ID,Name	Into :xID,:name
	From Ens_Config.Item 
	Where Name=:compNm)

if (SQLCODE = 0)
{

    set itm = ##class(Ens.Config.Item).%OpenId(xID)
    if ( (itm.GetSetting("MaxErrors", .pval) = 1) && ($GET(pval) > 0) )
    {
	    $$$TRACE( "GetSetting(MaxErrors): " _ $GET(pval))
    	set maxErr = pval
    }

}

Quit maxErr

 set maxRetries = 5

&sql(Select ID,Name	Into :xID,:name
	From Ens_Config.Item 
	Where Name=:compNm)

if (SQLCODE = 0)
{

    set itm = ##class(Ens.Config.Item).%OpenId(xID)
    if ( (itm.GetSetting("MaxRetries", .pval) = 1) && ($GET(pval) > 0) )
    {
	    $$$TRACE( "GetSetting(MaxRetries): " _ $GET(pval))
    	set maxRetries = pval
    }

}

Quit maxRetries

	 set tsc = $$$OK
	 $$$TRACE("Setting error for:" _ compNm)
	 if ($DATA(^ItfGlobalNumErr(compNm)) > 0)	{
        set ^ItfGlobalNumErr(compNm) = ^ItfGlobalNumErr(compNm) + 1     
	 }
     else {
        Set ^ItfGlobalNumErr(compNm) = 1
     }
     if (^ItfGlobalNumErr(compNm) > ..GetMaxError(compNm))
     {
	     Set tsc = ..DisableMsgError(compNm, "Exceeded Max Errors")

     }

	 Quit tsc

	 set tsc = $$$OK
	 // $$$LOGINFO("Resetting error for:" _ compNm)
	 if ($DATA(^ItfGlobalNumErr(compNm)) > 0)	{
        set ^ItfGlobalNumErr(compNm) = 1     
	 }
     else {
        Set ^ItfGlobalNumErr(compNm) = 1
     }
     Quit tsc

$$$TRACE($System.Status.GetErrorCodes(errStat) _ " ||| " _ $System.Status.GetErrorText(errStat) _ "status text: " _ $System.Status.GetOneStatusText(errStat))
if (errStat [ "ITFCOMMON")
{
    Set status = errStat
}
else { // Ensemble error, shutdown to fix the issue
	 Set status = $$$ERROR($$$ITFCOMMONDisableMsgError, "SYSTEM Error Code: "_ $System.Status.GetErrorCodes(errStat) _ " ||| " _ $System.Status.GetOneStatusText(errStat))
}
 Quit status

